import { randomUUID } from 'node:crypto';
import { copyFile, mkdir, readFile, unlink, writeFile } from 'node:fs/promises';
import { join, resolve } from 'node:path';
import { withCopySpace } from './disk-space.js';

const validKey = /^[a-f0-9-]{36}$/;

// The file key is generated by the server; callers never provide filesystem paths.
export class FileSourceStore {
  constructor(directory) {
    this.directory = resolve(directory);
  }
  path(key) {
    if (!validKey.test(key)) throw new Error('잘못된 코드 파일 식별자');
    return join(this.directory, `${key}.js`);
  }
  async put(source) {
    const key = randomUUID();
    await mkdir(this.directory, { recursive: true });
    await writeFile(this.path(key), source, { encoding: 'utf8', flag: 'wx' });
    return key;
  }
  async putFile(file) {
    const key = randomUUID();
    await mkdir(this.directory, { recursive: true });
    try {
      await withCopySpace(file, this.directory, () => copyFile(file, this.path(key)));
      return key;
    } catch (error) {
      await unlink(this.path(key)).catch(() => {});
      throw error;
    }
  }
  get(key) {
    return readFile(this.path(key), 'utf8');
  }
  delete(key) {
    return unlink(this.path(key));
  }
}
